<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1220;
      --panel: #111a2e;
      --panel-2: #162238;
      --text: #e5eefc;
      --muted: #9bb0d0;
      --border: #27405f;
      --accent: #6ea8ff;
      --accent-strong: #4f8dff;
      --error: #ff7f87;
      --success: #71d39b;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(110, 168, 255, 0.18), transparent 30%),
        linear-gradient(180deg, #08101d 0%, var(--bg) 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 640px);
      background: linear-gradient(180deg, rgba(17, 26, 46, 0.98), rgba(12, 19, 34, 0.98));
      border: 1px solid rgba(110, 168, 255, 0.18);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .support-card__header {
      padding: 28px 28px 10px;
      background: linear-gradient(180deg, rgba(22, 34, 56, 0.85), transparent);
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.7rem, 2.5vw, 2.2rem);
      line-height: 1.1;
    }

    .support-card__subtitle {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    form {
      padding: 18px 28px 28px;
    }

    .form-field {
      margin-bottom: 18px;
    }

    label {
      display: inline-block;
      margin-bottom: 8px;
      font-weight: 600;
      letter-spacing: 0.01em;
    }

    .required-marker {
      color: var(--accent);
    }

    input {
      width: 100%;
      padding: 14px 15px;
      border-radius: 14px;
      border: 1px solid var(--border);
      background: rgba(8, 16, 29, 0.95);
      color: var(--text);
      font: inherit;
      outline: none;
      transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
    }

    input::placeholder {
      color: #6f84a8;
    }

    input:focus {
      border-color: rgba(110, 168, 255, 0.95);
      box-shadow: 0 0 0 4px rgba(110, 168, 255, 0.14);
    }

    input[aria-invalid="true"] {
      border-color: rgba(255, 127, 135, 0.9);
      box-shadow: 0 0 0 4px rgba(255, 127, 135, 0.12);
    }

    .field-help,
    .field-error {
      display: block;
      margin-top: 8px;
      font-size: 0.93rem;
      line-height: 1.4;
    }

    .field-help {
      color: var(--muted);
    }

    .field-error {
      color: var(--error);
      min-height: 1.2em;
    }

    .actions {
      margin-top: 24px;
      display: flex;
      justify-content: flex-end;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 13px 22px;
      font: inherit;
      font-weight: 700;
      color: #07111f;
      background: linear-gradient(180deg, #8ab8ff, var(--accent-strong));
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(79, 141, 255, 0.28);
      transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.03);
      box-shadow: 0 18px 34px rgba(79, 141, 255, 0.34);
    }

    button:active {
      transform: translateY(0);
    }

    .status {
      margin-top: 16px;
      min-height: 1.4em;
      color: var(--success);
      font-weight: 600;
    }
  </style>
</head>
<body>
  <main class="support-card">
    <div class="support-card__header">
      <h1>Contact Support</h1>
      <p class="support-card__subtitle">Send us your details and we’ll get back to you as soon as possible.</p>
    </div>

    <form id="supportForm" novalidate>
      <div class="form-field">
        <label for="fullName">Full name <span class="required-marker">*</span></label>
        <input id="fullName" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required />
        <span class="field-error" id="fullNameError" aria-live="polite"></span>
      </div>

      <div class="form-field">
        <label for="email">Email address <span class="required-marker">*</span></label>
        <input id="email" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required />
        <span class="field-error" id="emailError" aria-live="polite"></span>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567" />
        <span class="field-help">Expected format: +1 (555) 123-4567 or 555-123-4567</span>
        <span class="field-error" id="phoneError" aria-live="polite"></span>
      </div>

      <div class="actions">
        <button type="submit">Submit</button>
      </div>

      <div class="status" id="formStatus" aria-live="polite"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('supportForm');
    const fullName = document.getElementById('fullName');
    const email = document.getElementById('email');
    const phone = document.getElementById('phone');
    const formStatus = document.getElementById('formStatus');

    const validators = {
      fullName(value) {
        if (!value.trim()) {
          return 'Full name is required.';
        }
        return '';
      },
      email(value) {
        if (!value.trim()) {
          return 'Email address is required.';
        }
        const pattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!pattern.test(value.trim())) {
          return 'Enter a valid email address.';
        }
        return '';
      },
      phone(value) {
        if (!value.trim()) {
          return '';
        }
        const pattern = /^(\+?\d{1,3}[\s.-]?)?(\(?\d{3}\)?[\s.-]?)\d{3}[\s.-]?\d{4}$/;
        if (!pattern.test(value.trim())) {
          return 'Enter a valid phone number using the expected format.';
        }
        return '';
      }
    };

    function setError(input, message) {
      const errorId = `${input.id}Error`;
      const errorElement = document.getElementById(errorId);
      errorElement.textContent = message;
      input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateField(input) {
      const message = validators[input.id](input.value);
      setError(input, message);
      return !message;
    }

    [fullName, email, phone].forEach((input) => {
      input.addEventListener('input', () => {
        validateField(input);
        formStatus.textContent = '';
      });
      input.addEventListener('blur', () => validateField(input));
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const isFullNameValid = validateField(fullName);
      const isEmailValid = validateField(email);
      const isPhoneValid = validateField(phone);

      if (isFullNameValid && isEmailValid && isPhoneValid) {
        formStatus.textContent = 'Thanks! Your message is ready to send.';
        form.reset();
        [fullName, email, phone].forEach((input) => setError(input, ''));
      } else {
        formStatus.textContent = '';
      }
    });
  </script>
</body>
</html>
